469	def _normalize_set_value(field_name, value):
470	    """校验 set 操作的值并返回最终入库值；非法时抛 BatchUpdateError。
471	
472	    去除前后空白；仅含空白按清空（None）处理；来源/地区/行业保留内部空白与换行；
473	    重要日期非空时须为 YYYY-MM-DD 真实日历日期。
474	    """
475	    if not isinstance(value, str):
476	        raise BatchUpdateError("%s的设置值不是文本" % FIELD_LABELS[field_name])
477	    text = value.strip()
478	    if not text:
479	        return None
480	    if field_name == "important_date":
481	        ok, reason = check_date(text)
482	        if not ok:
483	            raise BatchUpdateError(reason)
484	    return text
485	
486	
487	def batch_update_clients(database, payload):
488	    """执行批量修改，返回 {"updated_count": 去重后的客户数}；非法请求抛 BatchUpdateError。
489	
490	    任一问题都整次拒绝，不写入任何客户。
491	    """
492	    if not isinstance(payload, dict):
493	        raise BatchUpdateError("请求体必须是 JSON 对象")
494	
495	    raw_ids = payload.get("ids")
496	    if not isinstance(raw_ids, list):
497	        raise BatchUpdateError("ids 必须是客户编号数组")
498	    if not raw_ids:
499	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
500	
501	    ids = []
502	    seen_ids = set()
503	    for raw_id in raw_ids:
504	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
505	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
506	        if raw_id not in seen_ids:
507	            seen_ids.add(raw_id)
508	            ids.append(raw_id)
509	
510	    raw_updates = payload.get("updates", {})
511	    if not isinstance(raw_updates, dict):
512	        raise BatchUpdateError("updates 必须是字段修改说明对象")
513	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
514	    if extra:
515	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
516	
517	    actions = {}
518	    for field_name in OPTIONAL_FIELDS:
519	        spec = raw_updates.get(field_name, {"op": "keep"})
520	        if not isinstance(spec, dict):
521	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
522	        op = spec.get("op")
523	        if op not in ("keep", "set", "clear"):
524	            raise BatchUpdateError(
525	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
526	        if op == "keep":
527	            continue
528	        if op == "clear":
529	            actions[field_name] = None
530	        else:
531	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
532	
533	    if not actions:
534	        raise BatchUpdateError("全部字段均保持原值：请至少选择一个字段进行设置或清空")
535	
536	    placeholders = ",".join("?" for _ in ids)
537	    existing = {
538	        row[0]
539	        for row in database.execute(
540	            "SELECT id FROM clients WHERE id IN (%s)" % placeholders, ids
541	        )
542	    }
543	    missing = [cid for cid in ids if cid not in existing]
544	    if missing:
545	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
546	
547	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
548	    params = list(actions.values()) + ids
549	    try:
550	        database.execute(
551	            "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders), params
552	        )
553	        database.commit()
554	    except sqlite3.DatabaseError:
555	        database.rollback()
556	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
557	
558	    return {"updated_count": len(ids)}
559	
560	
561	def parse_csv(text):
562	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
563	
564	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
565	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
566	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
567	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
568	    - 文件结束时仍有字段处于引号内（引号未闭合）。
569	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
570	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
571	    """
572	    rows = []
573	    record = []
574	    field = []
575	    quoted = False        # 当前字段处于引号内
576	    started = False       # 当前字段已经开始（已有内容或已进入引号）
577	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
578	    record_number = 0     # 0 = 表头，1 起为数据记录
579	    i = 0
580	    n = len(text)
581	
582	    def location():
583	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
584	
585	    def structure_error(kind):
586	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
587	
588	    def finish_record():
589	        nonlocal record, field, started, closed
590	        record.append("".join(field))
591	        rows.append(record)
592	        record = []
593	        field = []
594	        started = False
595	        closed = False
596	
597	    while i < n:
598	        c = text[i]
599	        if quoted:
600	            if c == '"':
601	                if i + 1 < n and text[i + 1] == '"':
602	                    field.append('"')
603	                    i += 2
604	                    continue
605	                quoted = False
606	                closed = True
607	                i += 1
608	                continue
609	            if c == "\r":
610	                # 统一字段内换行符为 LF
611	                if i + 1 < n and text[i + 1] == "\n":
612	                    i += 1
613	                field.append("\n")
614	                i += 1
615	                continue
616	            field.append(c)
617	            i += 1
618	            continue
619	        if closed:
620	            # 引号已结束，只允许逗号、记录换行或文件结束
621	            if c == ",":
622	                record.append("".join(field))
623	                field = []
624	                started = False
625	                closed = False
626	            elif c in "\r\n":
627	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
628	                    i += 1
629	                finish_record()
630	                record_number += 1
631	            else:
632	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
633	            i += 1
634	            continue
635	        if c == '"' and not started:
636	            quoted = True
637	            started = True
638	        elif c == '"':
639	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
640	        elif c == ",":
641	            record.append("".join(field))
642	            field = []
643	            started = False
644	        elif c in "\r\n":
645	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
646	                i += 1
647	            if not started and not record and not field:
648	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
649	                i += 1
650	                continue
651	            finish_record()
652	            record_number += 1
653	        else:
654	            field.append(c)
655	            started = True
656	        i += 1
657	    if quoted:
658	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
659	    if started or field or record or closed:
660	        record.append("".join(field))
661	        rows.append(record)
662	    if not rows:
663	        raise FileError("CSV 内容为空：缺少表头")
664	    return rows[0], rows[1:]
665	
666	
667	def check_date(value):
668	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
669	    match = DATE_RE.match(value)
670	    if not match:
671	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
672	    try:
673	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
674	    except ValueError:
675	        return False, "重要日期无效（%s）：不是真实日历日期" % value
676	    return True, None
677	
678	
679	def import_clients(database, text):
680	    """执行导入，返回响应字典；文件级错误抛 FileError。"""
681	    header, data_rows = parse_csv(text)
682	    headers = [h.strip() for h in header]
683	
684	    seen = set()
685	    duplicates = []
686	    for h in headers:
687	        if h in seen and h not in duplicates:
688	            duplicates.append(h)
689	        seen.add(h)
690	    if duplicates:
691	        raise FileError("表头重复：%s" % "、".join(repr(h) for h in duplicates))
692	    unknown = [h for h in headers if h not in ALL_COLUMNS]
693	    if unknown:
694	        raise FileError("出现未知列：%s" % "、".join(repr(h) for h in unknown))
695	    if "name" not in headers:
696	        raise FileError("缺少名称列：表头必须包含 name 列")
697	
698	    index = {h: i for i, h in enumerate(headers)}
699	    name_index = index["name"]
700	    date_index = index.get("important_date")
701	
702	    existing = {}
703	    for cid, cname in database.execute("SELECT id, name FROM clients"):
704	        existing[(cname or "").strip().casefold()] = cid
705	
706	    imported = []
707	    failures = []
708	    seen_in_file = {}
709	
710	    for row_number, raw in enumerate(data_rows, start=1):
711	        if len(raw) != len(headers):
712	            failures.append({
713	                "row": row_number,
714	                "reason": "列数不符：表头有 %d 列，该记录有 %d 列" % (len(headers), len(raw)),
715	            })
716	            continue
717	
718	        name = raw[name_index].strip()
719	        problems = []
720	        if not name:
721	            problems.append("缺少名称：name 列为空")
722	        date_value = ""
723	        if date_index is not None:
724	            date_value = raw[date_index].strip()
725	            if date_value:
726	                ok, reason = check_date(date_value)
727	                if not ok:
728	                    problems.append(reason)
729	        if problems:
730	            failures.append({"row": row_number, "reason": "；".join(problems)})
731	            continue
732	
733	        key = name.casefold()
734	        if key in existing:
735	            failures.append({
736	                "row": row_number,
737	                "reason": "名称与已有客户重复（已有客户编号 %d），未更新" % existing[key],
738	            })
739	            continue
740	        if key in seen_in_file:
741	            failures.append({
742	                "row": row_number,
743	                "reason": "名称与文件内第 %d 条记录重复" % seen_in_file[key],
744	            })
745	            continue
746	
747	        seen_in_file[key] = row_number
748	        record = {"name": name}
749	        for field_name in OPTIONAL_FIELDS:
750	            idx = index.get(field_name)
751	            value = raw[idx].strip() if idx is not None else ""
752	            record[field_name] = value or None
753	        imported.append((row_number, record))
754	
755	    saved = []
756	    for row_number, record in imported:
757	        cursor = database.execute(
758	            "INSERT INTO clients (name, source, region, industry, important_date)"
759	            " VALUES (:name, :source, :region, :industry, :important_date)",
760	            record,
761	        )
762	        saved.append({"row": row_number, "id": cursor.lastrowid, "name": record["name"]})
763	    database.commit()
764	
765	    return {
766	        "imported_count": len(saved),
767	        "failed_count": len(failures),
768	        "imported": saved,
769	        "failures": failures,
770	    }
771	
772	
773	def main():
774	    parser = argparse.ArgumentParser(description="ClientBook - 客户联系人与商机记录")
775	    commands = parser.add_subparsers(dest="command", required=True)
776	    serve = commands.add_parser("serve", help="Start the HTTP service")
777	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
778	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
779	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
780	    args = parser.parse_args()
781	    if not 0 <= args.port <= 65535:
782	        parser.error("port must be between 0 and 65535")
783	    args.data_dir.mkdir(parents=True, exist_ok=True)
784	    database = sqlite3.connect(args.data_dir / "client-book.sqlite")
785	    database.execute("CREATE TABLE IF NOT EXISTS clients (id INTEGER PRIMARY KEY, name TEXT NOT NULL)")
786	    columns = {row[1] for row in database.execute("PRAGMA table_info(clients)")}
787	    for field_name in OPTIONAL_FIELDS:
788	        if field_name not in columns:
789	            database.execute("ALTER TABLE clients ADD COLUMN %s TEXT" % field_name)
790	    database.commit()
791	
792	    class Handler(BaseHTTPRequestHandler):
793	        def respond(self, status, value, *, html=False, allow=None):
794	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
795	            self.send_response(status)
796	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
797	            self.send_header("Content-Length", str(len(payload)))
798	            if status == 405:
799	                self.send_header("Allow", allow or "GET")
800	            self.end_headers()
801	            self.wfile.write(payload)
802	
803	        def handle_import(self):
804	            try:
805	                length = int(self.headers.get("Content-Length") or 0)
806	            except ValueError:
807	                length = 0
808	            if length > MAX_BODY:
809	                self.respond(400, {"error": "文件过大：超过 %d 字节上限" % MAX_BODY})
810	                return
811	            raw_body = self.rfile.read(length) if length > 0 else b""
812	            try:
813	                text = raw_body.decode("utf-8-sig")
814	            except UnicodeDecodeError:
815	                self.respond(400, {"error": "编码错误：文件不是有效的 UTF-8 文本"})
816	                return
817	            try:
818	                result = import_clients(database, text)
819	            except FileError as exc:
820	                database.rollback()
821	                self.respond(400, {"error": str(exc)})
822	                return
823	            self.respond(200, result)
824	
825	        def handle_batch_update(self):
826	            try:
827	                length = int(self.headers.get("Content-Length") or 0)
828	            except ValueError:
829	                length = 0
830	            if length > MAX_BODY:
831	                self.respond(400, {"error": "请求体过大：超过 %d 字节上限" % MAX_BODY})
832	                return
833	            raw_body = self.rfile.read(length) if length > 0 else b""
834	            try:
835	                payload = json.loads(raw_body.decode("utf-8"))
836	            except (UnicodeDecodeError, json.JSONDecodeError):
837	                self.respond(400, {"error": "请求体不是有效的 UTF-8 JSON 对象"})
838	                return
839	            try:
840	                result = batch_update_clients(database, payload)
841	            except BatchUpdateError as exc:
842	                database.rollback()
843	                self.respond(400, {"error": str(exc)})
844	                return
845	            self.respond(200, result)
846	
847	        def route(self):
848	            location = urlsplit(self.path).path
849	            if location not in (
850	                "/", "/health", "/api/clients",
851	                "/api/clients/import", "/api/clients/batch-update",
852	            ):
853	                self.respond(404, {"error": "not found"})
854	                return
855	            if location == "/api/clients/import":
856	                if self.command != "POST":
857	                    self.respond(405, {"error": "method not allowed"}, allow="POST")
858	                    return
859	                self.handle_import()
860	                return
861	            if location == "/api/clients/batch-update":
862	                if self.command != "POST":
863	                    self.respond(405, {"error": "method not allowed"}, allow="POST")
864	                    return
865	                self.handle_batch_update()
866	                return
867	            if self.command != "GET":
868	                self.respond(405, {"error": "method not allowed"}, allow="GET")
869	                return
870	            if location == "/":
871	                self.respond(200, PAGE, html=True)
872	            elif location == "/health":
873	                self.respond(200, {"status": "ok", "product": PRODUCT})
874	            else:
875	                records = [
876	                    {
877	                        "id": row[0],
878	                        "name": row[1],
879	                        "source": row[2],
880	                        "region": row[3],
881	                        "industry": row[4],
882	                        "important_date": row[5],
883	                    }
884	                    for row in database.execute(
885	                        "SELECT id, name, source, region, industry, important_date FROM clients ORDER BY id"
886	                    )
887	                ]
888	                self.respond(200, {RESOURCE: records})
889	
890	        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_HEAD = do_OPTIONS = route
891	
892	    def stop(_signal, _frame):
893	        raise KeyboardInterrupt
894	
895	    signal.signal(signal.SIGTERM, stop)
896	    server = None
897	    try:
898	        server = HTTPServer((args.host, args.port), Handler)
899	        host, port = server.server_address[:2]
900	        address = f"[{host}]" if ":" in host else host
901	        print(f"{PRODUCT} listening on http://{address}:{port}", flush=True)
902	        server.serve_forever()
903	    except KeyboardInterrupt:
904	        pass
905	    finally:
906	        if server is not None:
907	            server.server_close()
908	        database.close()
909	
910	
911	if __name__ == "__main__":
912	    main()
