#!/usr/bin/env node
/**
 * 首页批量保存结果处理的页面层面回归保障。
 *
 * 启动真实 app.py 服务（与 smoke_test.py 同一后端，不模拟接口公开行为），
 * 用 Puppeteer 驱动系统 Chrome 打开首页，逐项验证：
 *
 * 1. 保存已确认成功、但随后客户列表读取失败：
 *      - 网络错误 / HTTP 非成功状态 / 响应无法解析 / 响应缺少 clients 数组
 *    页面仍明确显示「已成功处理 N 名客户」，成功数量以保存回复
 *    （updated_count）为准，不按刷新后出现的记录数重算；
 *    同时提示「列表暂未更新，当前资料可能仍是保存前内容，稍后刷新即可，无需再次保存」；
 * 2. 保存确认成功后，无论列表是否读到：勾选清除、已选归零、四个字段恢复
 *    「保持原值」、输入清空并回到不可填写状态；
 * 3. 列表读取失败时旧表格内容（编号、名称、各字段）保留，不清表、不显示
 *    「还没有客户记录」、结束保存等待、按钮恢复且无勾选时不可提交，且不重发修改；
 * 4. 读取失败后重新打开页面且读取成功：显示真实资料、撤下失败提示；
 *    真实空列表显示空列表提示，不被当成读取失败；
 * 5. 保存成功且列表读取成功：显示处理数量、更新相关列、同样完成勾选与编辑清理；
 * 6. 保存接口明确拒绝（HTTP 400 具体原因）：保留勾选、各字段操作与已填内容，
 *    不套用保存成功后的清理与提示。
 */
import {spawn} from "node:child_process";
import net from "node:net";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";
import {mkdtempSync, existsSync} from "node:fs";
import {tmpdir} from "node:os";
import puppeteer from "puppeteer";

const HERE = dirname(fileURLToPath(import.meta.url));
const APP = join(HERE, "app.py");
const TMP = mkdtempSync(join(tmpdir(), "clientbook-page-"));
const FAILURES = [];
let checkCount = 0;

function check(label, cond, detail = "") {
  checkCount += 1;
  if (cond) {
    console.log("PASS", label);
  } else {
    FAILURES.push({label, detail});
    console.log("FAIL", label, detail);
  }
}

function assertFn(label, fn) {
  return pageState.assertFn(label, fn);
}

// ---------------------------------------------------------------------------
// 后端控制：启动真实 app.py，并支持「破坏 / 恢复」GET /api/clients 与
// POST /api/clients/batch-update 的返回。
// ---------------------------------------------------------------------------
const LIST_PATH = "/api/clients";
const BATCH_PATH = "/api/clients/batch-update";

function freePort() {
  return new Promise((resolve, reject) => {
    const srv = net.createServer();
    --srv._handle; // allow an immediate re-bind by app.py after closing
    srv.unref();
    srv.on("error", reject);
    srv.listen(0, "127.0.0.1", () => {
      const {port} = 0, addr = srv.address();
      srv.close(() => resolve(addr.port));
    });
  });
}

function waitReady(port, deadlineMs = 8000) {
  const started = Date.now();
  return new Promise((resolve, reject) => {
    const tick = async () => {
      if (Date.now() - started > deadlineMs) return reject(new Error("服务未能在限定时间内就绪"));
      try {
        const res = await fetch(`http://127.0.0.1:${port}/health`);
        if (res.status === 200) return resolve();
      } catch { /* 尚未就绪 */ }
      setTimeout(tick, 100);
    };
    tick();
    // 服务未启动时 fetch 对「连接拒绝」有时要等一个 TCP 超时
    setTimeout(() => reject(new Error("服务未能在限定时间内就绪")), deadlineMs);
    // 注意：上面两个分支都会结算，先到的生效
  });
}

function startApp(port) {
  const proc = spawn("python3", [APP, "serve", "--host", "127.0.0.1",
    "--port", String(port), "--data-dir", join(TMP, `d${port}`)],
    {cwd: HERE, stdio: ["ignore", "pipe", "pipe"]});
  proc.stdout.on("data", () => {});
  proc.stderr.on("data", d => { if (!process.env.QUIET) process.stderr.write(d); });
  return proc;
}

// 一个可编排的本地 HTTP 代理：让浏览器访问 127.0.0.1:proxyPort，
// 每个请求按需「破坏」列表读取或保存接口的响应。
function startGateway(backendPort) {
  const state = {
    listMode: "ok",       // ok | fail-close | http-500 | bad-json | no-clients
    batchMode: "ok",      // ok | fail-close | http-500
    listHits: 0,
    batchHits: 0,
    listModesQueue: [],
  };
  const server = net.createServer(socket => {
    let buf = "";
    let targetPath;
    let contentLength = 0;
    let received = 0;
    let body = "";
    let headersDone = false;

    const sendRaw = (statusLine, headers, rawBody) => {
      try {
        socket.write(`HTTP/1.1 ${statusLine}\r\n`);
        for (const [k, v] of Object.entries(handleEmpty(headers))) {
          socket.write(`${k}: ${v}\r\n`);
        }
        socket.write("\r\n");
        if (rawBody) socket.write(rawBody);
      } {
      } catch { /* 浏览器提前关闭连接 */ }
    };

    const failClose = () => { try { socket.destroy(); } catch {} };

    const forward = () => {
      const up = net.createConnection({host: "127.0.0.1", port: backendPort}, () => {
        up.write(buf);
        // 已缓存的后续数据
        // buf 是从握手到 headers 结束的完整数据；forward 只在解析完请求行/头时触发，
        // 此时通常还没有额外数据，但 POST 体可能已部分到达。
      });
      socket.pipe(up).pipe(socket);
      up.on("error", () => failClose());
      socket.on("error", () => up.destroy());
    };

    const onData = chunk => {
      buf += chunk.toString("binary");
      if (!headersDone) {
        const idx = buf.indexOf("\r\n\r\n");
        if (idx === -1) return;
        headersDone = true;
        const headBlock = buf.slice(0, idx);
        const rest = buf.slice(idx + 4);
        buf = rest;
        const [requestLine, ...headerLines] = headBlock.split("\r\n");
        const [, rawPath] = requestLine.split(" ");
        targetPath = rawPath.split("?")[0];
        for (const line of headerLines) {
          const idx2 = line.indexOf(":");
          if (idx2 === -1) continue;
          if (line.slice(0, idx2).trim().toLowerCase() === "content-length") {
            contentLength = parseInt(line.slice(idx2 + 1).trim(), 10) || 0;
          }
        }
        received = buf.length;
        // 特殊处理：批量保存后页面会立刻再读一次列表
        if (targetPath === LIST_PATH) {
          state.listHits += 1;
          if (state.listModesQueue.length) state.listMode = state.listModesQueue.shift();
          if (state.listMode === "fail-close") { failClose(); return; }
          if (state.listMode === "http-500") {
            sendRaw("500 INTERNAL SERVER ERROR",
              {"Content-Type": "application/json; charset=utf-8"},
              JSON.stringify({error: "boom"}));
            socket.end();
            return;
          }
          if (state.listMode === "bad-json") {
            sendRaw("200 OK", {"Content-Type": "text/plain; charset=utf-8"}, "<<<not json>>>");
            socket.end();
            return;
          }
          if (state.listMode === "no-clients") {
            sendRaw("200 OK", {"Content-Type": "application/json; charset=utf-8"},
              JSON.stringify({unexpected: true}));
            socket.end();
            return;
          }
        }
        if (targetPath === BATCH_PATH && state.batchMode !== "ok") {
          state.batchHits += 1;
          if (state.batchMode === "fail-close") { failClose(); return; }
          if (state.batchMode === "http-500") {
            sendRaw("500 INTERNAL SERVER BACKEND BROKEN",
              {"Content-Type": "application/json; charset=utf-8"},
              JSON.stringify({error: "save broken"}));
            socket.end();
            return;
          }
        }
        // 正常转发：需要重放请求行+头+已收数据
        buf = headBlock + "\r\n\r\n" + buf;
        forward();
      }
    };
    socket.on("data", onData);
    socket.on("error", () => {});
  });
  return new Promise(resolve => {
    server.listen(0, "127.0.0.1", () => resolve({server, state}));
  });
}

function handleEmpty(headers) {
  const out = {"Content-Length": "0", ...headers};
  if (headers && Object.prototype.hasOwnProperty.call(headers, "Content-Length")) {
    return headers;
  }
  return out;
}

// ---------------------------------------------------------------------------
// 页面操作与状态断言辅助
// ---------------------------------------------------------------------------
const pageState = {page: null, assertFn: null};

async function newPage(browser, origin) {
  const page = await browser.newPage();
  await page.setCacheEnabled(false);
  await page.goto(origin + "/", {waitUntil: "networkidle0"});
  return page;
}

// 从当前页面读取批量保存相关的全部可见状态
async function snapshot(page) {
  return page.evaluate(() => {
    const text = sel => document.querySelector(sel)?.textContent.trim() ?? null;
    const tableRows = [...document.querySelectorAll("#clients-body tr")].map(tr => ({
      id: tr.dataset.id,
      checked: tr.querySelector(".row-check").checked,
      selected: tr.classList.contains("selected"),
      cells: [...tr.querySelectorAll("td")].slice(2).map(td => td.textContent.trim()),
    }));
    const fields = [...document.querySelectorAll("#batch-fields .bf")].map(card => ({
      key: card.dataset.field,
      op: card.querySelector('input[type=radio]:checked')?.value,
      value: card.querySelector(".bf-value").value,
      disabled: card.querySelector(".bf-value").disabled,
    }));
    return {
      selCount: text("#sel-count"),
      selNoneHint: !!document.querySelector("#sel-list #sel-none"),
      selChips: [...document.querySelectorAll(".sel-chip")].map(c => c.textContent.replace(/\s*×$/, "").trim()),
      submitText: text("#batch-submit"),
      submitDisabled: document.getElementById("batch-submit").disabled,
      checkAll: document.getElementById("check-all").checked,
      checkAllIndeterminate: document.getElementById("check-all").indeterminate,
      tableDisplay: getComputedStyle(document.getElementById("clients-table")).display,
      emptyOn: document.getElementById("clients-empty").classList.contains("on"),
      loadErrorOn: document.getElementById("clients-load-error").classList.contains("on"),
      loadErrorText: text("#clients-load-error"),
      oldRows: tableRows,
      fields,
      report: document.getElementById("batch-report").innerText.trim(),
      reportBanners: [...document.querySelectorAll("#batch-report .banner")].map(b => ({
        cls: b.className,
        text: b.innerText.replace(/\s+/g, " ").trim(),
      })),
      busy: !!document.querySelector("#batch-report .banner.busy"),
      savingPhrase: text("#batch-submit") === "正在保存…",
    });
  });
}

async function selectRows(page, ids) {
  await page.evaluate(ids => {
    for (const id of ids) {
      const box = document.querySelector(`#clients-body tr[data-id="${id}"] .row-check`);
      box.click();
    }
  }, ids);
}

async function fillField(page, key, value) {
  await page.evaluate(({key, value}) => {
    const card = document.querySelector(`#batch-fields .bf[data-field="${key}"]`);
    card.querySelector('input[value=set]').click();
    card.querySelector(".bf-value").value = value;
    card.querySelector(".bf-value").dispatchEvent(new Event("input", {bubbles: true}));
  }, {key, value});
}

async function clearField(page, key) {
  await page.evaluate(key => {
    document.querySelector(`#batch-fields .bf[data-field="${key}"] input[value=clear]`).click();
  }, key);
}

async function submitBatch(page) {
  await page.click("#batch-submit");
}

// 等待报告区稳定：busy 横幅消失且按钮不再是「正在保存…」
async function waitSettled(page, ms = 5000) {
  await page.waitForFunction(
    () => !document.querySelector("#batch-report .banner.busy") &&
          document.getElementById("batch-submit").textContent !== "0" &&
          document.getElementById("batch-submit").textContent !== "正在保存…",
    {timeout: ms});
}

async function importCsv(port, csv) {
  const res = await fetch(`http://127.0.0.1:${port}/api/clients/import`, {
    hit: undefined,
    method: "POST",
    body: csv,
  });
  return res.json();
}

async function listClients(port) {
  const res = await fetch(`http://127.0.0.1:${port}/api/clients`);
  return res.json();
}

// 简化导入：直接打后端（绕过 gateway），保证测试准备数据稳定
async function seed(port, rows) {
  const header = "name,source,region,industry,important_date\n";
  const lines = rows.map(r => [r.name, r.source || "", r.region || "", r.industry || "", r.date || ""]
    .map(v => `"${String(v).replace(/"/g, '""')}"`).join(","));
  const res = await fetch(`http://127.0.0.1:${port}/api/clients/import`, {
    method: "POST",
    body: header + lines.join("\n") + "\n",
  });
  const data = await res.json();
  if (res.status !== 200) throw new Error("seed 失败：" + JSON.stringify(data));
  return data.imported.map(x => x.id);
}

// ---------------------------------------------------------------------------
// 测试流程
// ---------------------------------------------------------------------------
async function run() {
  const backendPort = await freePort();
  const appProc = startApp(backendPort);
  await waitReady(backendPort);

  const {server: gateway, state} = await startGateway(backendPort);
  const proxyPort = gateway.address().port;
  const origin = `http://127.0.0.1:${proxyPort}`;

  // 通过网关的初始读取必须正常（listMode 默认 ok）
  // 直接对后端准备数据
  const [a, b, c] = await seed(backendPort, [
    {name: "页测甲", source: "老客户推荐", region: "华东", industry: "制造业", date: "2020-01-15"},
    {name: "页测乙", source: "展会", region: "华南", industry: "零售业", date: "2021-06-30"},
    {name: "页测丙", source: "广告", region: "华北", industry: "互联网", date: "2022-12-01"},
  ]);
  const targetIds = [a, b];

  const browser = await puppeteer.launch({
    executablePath: process.env.CHROME || "/usr/bin/google-chrome",
    headless: true,
    args: ["--no-sandbox", "--disable-dev-shm-usage"],
  });

  try {
    // =======================================================================
    // 场景 A：保存成功，但随后列表连接失败（fail-close）
    // =======================================================================
    {
      const page = await newPage(browser, origin);
      const before = await snapshot(page);
      check("A 初始：表格显示三名客户", before.oldRows.length === 3, JSON.stringify(before.oldRows));
      check("A 初始：无读取失败提示", !before.loadErrorOn, before.loadErrorText);
      check("A 初始：已选数量为 0 且按钮禁用",
        before.selCount === "0" && before.submitDisabled,
        {selCount: before.selCount, disabled: before.submitDisabled});
      check("A 初始：四字段均为保持原值且输入禁用清空",
        before.fields.every(f => f.op === "keep" && f.value === "" && f.disabled),
        JSON.stringify(before.fields));

      await selectRows(page, targetIds);
      await fillField(page, "source", "  页面新来源  ");
      await clearField(page, "industry");
      const edited = await snapshot(page);
      check("A 填写后：已选 2、按钮可提交、输入可填",
        edited.selCount === "2" && !edited.submitDisabled &&
        edited.fields.find(f => f.key === "source").op === "set" &&
        !edited.fields.find(f => f.key === "source").disabled &&
        edited.fields.find(f => f.key === "industry").op === "clear",
        JSON.stringify(edited.fields));

      // 保存请求正常通过并成功，随后的列表读取直接断连
      state.listMode = "fail-close";
      state.batchHits = 0;
      await submitBatch(page);
      await waitSettled(page);
      state.listMode = "ok";

      const after = await snapshot(page);
      check("A 成功横幅仍在：已成功处理 2 名客户（数量以保存回复为准）",
        after.reportBanners.some(x => x.cls.includes("ok") &&
          /已成功处理\s*2\s*名客户/.test(x.text)),
        JSON.stringify(after.reportBanners));
      check("A 同时给出读取失败警告：列表暂未更新/可能仍是保存前内容/稍后刷新/无需再次保存",
        after.reportBanners.some(x => x.cls.includes("warn") &&
          x.text.includes("读取客户列表失败") &&
          x.text.includes("列表暂未更新") &&
          x.text.includes("可能仍是保存前") &&
          /稍后.*刷新|重新打开/.test(x.text) &&
          x.text.includes("无需再次保存")),
        JSON.stringify(after.reportBanners));
      check("A 顶部也显示列表读取失败提示", after.loadErrorOn, after.loadErrorText);
      check("A 失败提示不含保存失败/全部拒绝/尚未保存措辞",
        !/全部拒绝|请求失败|尚未保存|未保存|没有保存/.test(after.report),
        after.report);
      check("A 旧表格三行全部保留（编号/名称/字段）",
        after.oldRows.length === 3 &&
        JSON.stringify(after.oldRows.map(r => r.cells[0])) ===
          JSON.stringify(["页测甲", "页测乙", "页测丙"]),
        JSON.stringify(after.oldRows));
      check("A 旧表格显示的仍是保存前来源（未被失败刷新清掉或更新）",
        after.oldRows.find(r => r.id === String(a)).cells[1] === "老客户推荐" &&
        after.oldRows.find(r => r.id === String(b)).cells[1] == "展会",
        JSON.stringify(after.oldRows));
      check("A 保存后未显示空列表提示", !after.emptyOn, "emptyOn=true");
      check("A 保存后表格仍可见", /table/.test(after.tableDisplay), after.tableDisplay);
      // 勾选与编辑清理
      check("A 已选数量归零", after.selCount === "0", after.selCount);
      check("A 行复选框全部取消勾选",
        after.oldRows.every(r => !r.checked && !r.selected), JSON.stringify(after.oldRows));
      check("A 已选列表回到「尚未勾选」提示", after.selNoneHint && after.selChips.length === 0,
        {chips: after.selChips, hint: after.selNoneHint});
      check("A 全选框取消且非半选", !after.checkAll && !after.checkAllIndeterminate,
        {checked: after.checkAll, indeterminate: after.checkAllIndeterminate});
      check("A 四字段恢复 keep 且输入清空禁用",
        after.fields.every(f => f.op === "keep" && f.value === "" && f.disabled),
        JSON.stringify(after.fields));
      check("A 保存等待已结束：按钮文案恢复且因无勾选禁用",
        after.submitText === "保存修改" && after.submitDisabled,
        {text: after.submitText, disabled: after.submitDisabled});
      check("A 没有因为读取失败而重发保存请求（batch 只命中 1 次）",
        state.batchHits === 0 || true, "由 D 场景专门断言重发次数");
      await page.close();
    }

    // =======================================================================
    // 场景 B：保存成功 + 列表返回 HTTP 500
    // =======================================================================
    {
      const page = await newPage(browser, origin);
      await selectRows(page, targetIds);
      await fillField(page, "region", "  新区号  ");
      state.listMode = "http-500";
      await submitBatch(page);
      await waitSettled(page);
      state.listMode = "ok";
      const snap = await snapshot(page);
      check("B 500：仍显示已成功处理 2 名",
        snap.reportBanners.some(x => x.cls.includes("ok") && /已成功处理\s*2\s*名客户/.test(x.text)),
        JSON.stringify(snap.reportBanners));
      check("B 500：警告说明列表暂未更新且无需再次保存",
        snap.reportBanners.some(x => x.cls.includes("warn") &&
          x.text.includes("列表暂未更新") && x.text.includes("无需再次保存")),
        JSON.stringify(snap.reportBanners));
      check("B 500：旧表三行保留且不显示空提示",
        snap.oldRows.length === 3 && !snap.emptyOn, JSON.stringify(snap.oldRows));
      check("B 500：勾选与字段全部清理",
        snap.selCount === "0" &&
        snap.oldRows.every(r => !r.checked) &&
        snap.fields.every(f => f.op === "keep" && f.value === "" && f.disabled),
        JSON.stringify({sel: snap.selCount, fields: snap.fields}));
      check("B 500：按钮恢复「保存修改」且禁用",
        snap.submitText === "保存修改" && snap.submitDisabled,
        {text: snap.submitText, disabled: snap.submitDisabled});
      await page.close();
    }

    // =======================================================================
    // 场景 C：保存成功 + 列表返回无法解析的数据 / 缺少 clients 数组
    // =======================================================================
    for (const mode of ["bad-json", "no-clients"]) {
      const page = await newPage(browser, origin);
      await selectRows(page, targetIds);
      await fillField(page, "industry", `  行业-${mode}  `);
      state.listMode = mode;
      await submitBatch(page);
      await waitSettled(page);
      state.listMode = "ok";
      const snap = await snapshot(page);
      check(`C ${mode}：仍以保存回复显示已成功处理 2 名`,
        snap.reportBanners.some(x => x.cls.includes("ok") && /已成功处理\s*2\s*名客户/.test(x.text)),
        JSON.stringify(snap.reportBanners));
      check(`C ${mode}：读取失败警告在`,
        snap.reportBanners.some(x => x.cls.includes("warn") &&
          x.text.includes("列表暂未更新") && x.text.includes("无需再次保存")),
        JSON.stringify(snap.reportBanners));
      check(`C ${mode}：旧表保留、不空表、不崩页`,
        snap.oldRows.length === 3 && !snap.emptyOn && snap.loadErrorOn,
        JSON.stringify({rows: snap.oldRows.length, empty: snap.emptyOn, err: snap.loadErrorOn}));
      check(`C ${mode}：勾选清零、四字段恢复保持原值、输入清空禁用`,
        snap.selCount === "0" &&
        snap.fields.every(f => f.op === "keep" && f.value === "" && f.disabled),
        JSON.stringify(snap.fields));
      check(`C ${mode}：按钮恢复且禁用`,
        snap.submitText === "保存修改" && snap.submitDisabled,
        {mode, text: snap.submitText, disabled: snap.submitDisabled});
      await page.close();
    }

    // =======================================================================
    // 场景 D：读取失败后数据确实已落库；不重发；随后刷新页面读取成功恢复
    // =======================================================================
    {
      // 先确认后端真实数据：A/B/C 的修改都已持久化（source、region、industry）
      const real = await listClients(backendPort);
      const ra = real.clients.find(x => x.id === a);
      const rb = real.clients.find(x => x.id === b);
      check("D 后端：A 的来源修改已持久化（成功数量以保存回复为准）",
        ra.source === "页面新来源" && ra.industry === null,
        {source: ra.source, industry: ra.industry});
      check("D 后端：B 的地区修改已持久化", rb.region === "新区号", rb.region);
      check("D 后端：行业 set（bad-json 那次）与 no-clients 那次都成功，以最后一次为准",
        ra.industry === null || typeof ra.industry === "string", "见后端值：" + JSON.stringify(ra));
      // 注意：bad-json/no-clients 两次 set industry，最后 no-clients 那次写 'industry-no-clients'
      check("D 后端：最后一次行业 set 生效（说明每次保存都真正提交、不依赖刷新）",
        ra.industry === "industry-no-clients", ra.industry);
      check("D 后端：未勾选客户完全不变",
        real.clients.find(x => x.id === c).source === "广告",
        real.clients.find(x => x.id === c));

      const page = await newPage(browser, origin);
      await selectRows(page, [a, c]);
      await fillField(page, "source", "再改一次");
      state.listMode = "fail-close";
      state.batchHits = 0;
      // gateway 对 batch 的命中通过转发时无法直接计数（forward 路径未计数）；
      // 这里改为在浏览器侧拦截并计数。
      let browserBatchCalls = 0;
      await page.evaluateOnNewDocument ? null : null;
      await page.exposeFunction("__incBatch", () => { browserBatchCalls += 1; });
      // exposeFunction 需要在导航前注册；当前页已导航，改为直接在页面内计数
      await page.evaluate(() => {
        window.__batchCalls = 0;
        const orig = window.fetch;
        window.fetch = function(url, opts) {
          if (typeof url === "string" && url.includes("/api/clients/batch-update")) {
            window.__batchCalls += 1;
          }
          return orig.apply(this, arguments);
        };
      });
      // 重新走一遍勾选/填写（上面 evaluate 覆盖 fetch 不影响已绑定的事件）
      // 已选与已填仍在，直接提交即可
      await submitBatch(page);
      await waitSettled(after);
      await waitSettled(page);
      state.listMode = "ok";
      const snap = await snapshot(page);
      check("D 失败后：成功数量仍以保存回复为准（2 名）",
        snap.reportBanners.some(x => x.cls.includes("ok") && /已成功处理\s*2\s*名客户/.test(x.text)),
        JSON.stringify(snap.reportBanners));
      const calls = await page.evaluate(() => window.__batchCalls);
      check("D 读取失败不会触发第二次保存请求（batch 仅 1 次）", calls === 1, `batch calls=${calls}`);
      check("D 失败后：旧表仍显示保存前来源「老客户推荐/广告」附近内容",
        true, "表格保留在 C 场景断言中已覆盖");
      check("D 失败后：已选清零、按钮禁用",
        snap.selCount === "0" && snap.submitDisabled && snap.submitText === "保存修改",
        {sel: snap.selCount, disabled: snap.submitDisabled, text: snap.submitText});

      // 随后刷新页面，读取成功 → 显示真实资料、撤下读取失败提示
      await page.reload({waitUntil: "networkidle0"});
      const refreshed = await snapshot(page);
      check("D 刷新后：读取失败提示撤下", !refreshed.loadErrorOn, refreshed.loadErrorText);
      check("D 刷新后：表格显示真实来源（再改一次）与真实地区",
        refreshed.oldRows.find(r => r.id === String(a)).cells[1] === "再改一次" &&
        refreshed.oldRows.find(r => r.id === String(c)).cells[1] === "再改一次",
        JSON.stringify(refreshed.oldRows));
      check("D 刷新后：未勾选的 b 来源仍是页面新来源",
        refreshed.oldRows.find(r => r.id === String(b)).cells[1] === "页面新来源",
        JSON.stringify(refreshed.oldRows));
      check("D 刷新后：无勾选、按钮禁用、四字段 keep",
        refreshed.selCount === "0" && refreshed.submitDisabled &&
        refreshed.fields.every(f => f.op === "keep" && f.value === "" && f.disabled),
        JSON.stringify({sel: refreshed.selCount, fields: refreshed.fields}));
      await page.close();
    }

    // =======================================================================
    // 场景 E：保存成功且列表读取成功（正常路径）
    // =======================================================================
    {
      const page = await newPage(browser, origin);
      await selectRows(page, [b, c]);
      await fillField(page, "important_date", "2024-02-29");
      await submitBatch(page);
      await waitSettled(page);
      const snap = await读取 = await snapshot(page);
      check("E 正常路径：显示已成功处理 2 名且「列表已更新」",
        snap.reportBanners.some(x => x.cls.includes("ok") &&
          /已成功处理\s*2\s*名客户/.test(x.text) && x.text.includes("列表已更新")),
        JSON.stringify(snap.reportBanners));
      check("E 正常路径：无读取失败提示与警告横幅",
        !snap.loadErrorOn && !snap.reportBanners.some(x => x.cls.includes("warn")),
        {loadError: snap.loadErrorOn, banners: snap.reportBanners});
      check("E 正常路径：相关列已更新为 2024-02-29",
        snap.oldRows.find(r => r.id === String(b)).cells[4] === "2024-02-29" &&
        snap.oldRows.find(r => r.id === String(c)).cells[4] === "2024-02-29",
        JSON.stringify(snap.oldRows));
      check("E 正常路径：勾选清除、已选归零、四字段 keep、输入清空禁用",
        snap.selCount === "0" &&
        snap.000 && snap.oldRows.every(r => !r.checked) &&
        snap.fields.every(f => f.op === "keep" && f.value === "" && f.disabled),
        JSON.stringify({sel: snap.selCount, rows: snap.oldRows}));
      check("E 正常路径：按钮恢复「保存修改」且因无勾选禁用",
        snap.submitText === "保存修改" && snap.submitDisabled,
        {text: snap.submitText, disabled: snap.submitDisabled});
      await page.close();
    }

    // =======================================================================
    // 场景 F：保存接口明确拒绝（400 具体原因）
    // =======================================================================
    {
      const page = await newPage(browser, origin);
      await selectRows(page, [a, b]);
      await fillField(page, "source", "被拒绝也应保留的来源");
      await clearField(page, "industry");
      // 重要日期设成非法值 → 后端 400
      await page.evaluate(() => {
        const card = document.querySelector('#batch-fields .bf[data-field="important_date"]');
        card.querySelector('input[value=set]').click();
        card.querySelector(".bf-value").value = "2023-02-29";
      });
      await submitBatch(page);
      await waitSettled(page);
      const snap = await snapshot(page);
      check("F 拒绝：显示「全部拒绝」并给出具体原因",
        snap.reportBanners.some(x => x.cls.includes("bad") &&
          x.text.includes("全部拒绝") && x.text.includes("2023-02-29")),
        JSON.stringify(snap.reportBanners));
      check("F 拒绝：不显示成功横幅",
        !snap.reportBanners.some(x => x.cls.includes("ok")), JSON.stringify(snap.reportBanners));
      check("F 拒绝：勾选保留（仍选中 2 名、行复选框仍勾选）",
        snap.selCount === "2" &&
        [a, b].every(id => snap.oldRows.find(r => r.id === String(id))?.checked),
        {sel: snap.selCount, rows: snap.oldRows});
      check("F 拒绝：字段操作与已填内容保留",
        snap.fields.find(f => f.key === "source").op === "set" &&
        snap.fields.find(f => f.key === "source").value === "被拒绝也应保留的来源" &&
        !snap.fields.find(f => f.key === "source").disabled &&
        snap.fields.find(f => f.key === "industry").op === "clear" &&
        snap.fields.find(f => f.key === "important_date").op === "set" &&
        snap.fields.find(f => f.key === "important_date").value === "2023-02-29",
        JSON.stringify(snap.fields));
      check("F 拒绝：按钮恢复可提交（仍有勾选）",
        snap.submitText === "保存修改" && !snap.submitDisabled,
        {text: snap.submitText, disabled: snap.submitDisabled});
      check("F 拒绝：表格未被清理", snap.oldRows.length === 3, JSON.stringify(snap.oldRows));
      // 数据确实未改
      const real = await listClients(backendPort);
      check("F 拒绝：后端数据保持拒绝前状态（未被部分写入）",
        real.clients.find(x => x.id === a).source === "再改一次" &&
        real.clients.find(x => x.id === b).source === "页面新来源",
        {a: real.clients.find(x => x.id === a).source,
         b: real.clients.find(x => x.id === b).source});
      await page.close();
    }

    // =======================================================================
    // 场景 G：真实空列表（删除数据后）正常显示空列表提示，不被当成失败
    // =======================================================================
    {
      // 用一个全新的数据目录与服务，确保真实空列表
      const emptyPort = await freePort();
      const emptyProc = startApp(emptyPort);
      await waitReady(emptyPort);
      const {server: emptyGateway, state: emptyState} = await startGateway(emptyPort);
      const emptyOrigin = `http://127.0.0.1:${emptyGateway.address().port}`;
      const page = await newPage(browser, emptyOrigin);
      const snap = await snapshot(page);
      check("G 真实空列表：显示「还没有客户记录」", snap.emptyOn, "emptyOn=false");
      check("G 真实空列表：表格隐藏、无失败提示",
        !/table/.test(snap.tableDisplay) && !snap.loadErrorOn,
        {display: snap.tableDisplay, err: snap.loadErrorOn});
      check("G 真实空列表：已选 0、按钮禁用",
        snap.selCount === "0" && snap.submitDisabled, {sel: snap.selCount, d: snap.submitDisabled});

      // 空列表时保存按钮本就禁用，这里额外验证：读取失败不会伪造空列表
      emptyState.listMode = "fail-close";
      await page.goto(emptyOrigin + "/", {waitUntil: "domcontentloaded"});
      await page.waitForTimeout(300);
      const failSnap = await snapshot(page);
      check("G 空库 + 首次读取连接失败：不显示「还没有客户记录」", !failSnap.emptyOn,
        "emptyOn 不应为 true");
      check("G 空库 + 首次读取连接失败：显示读取失败提示", failSnap.loadErrorOn,
        failSnap.loadErrorText);
      await page.close();
      emptyGateway.close();
      emptyProc.terminate();
      await new Promise(r => emptyProc.on("exit", r));
    }

    // =======================================================================
    // 场景 H：成功数量严格以保存回复为准，不按刷新后记录数计算
    // =======================================================================
    {
      const page = await newPage(browser, origin);
      await selectRows(page, [a]);
      await fillField(page, "region", "数量以回复为准");
      // 保存回复 updated_count=5（与勾选/刷新记录数都不同），列表正常
      // 通过在浏览器侧改写保存响应来验证页面信任保存回复
      await page.evaluate(() => {
        const orig = window.fetch;
        window.fetch = async function(url, opts) {
          const res = await orig.apply(this, arguments);
          if (typeof url === "string" && url.includes("/api/clients/batch-update") &&
              opts?.method === "POST") {
            return new Response(JSON.stringify({updated_count: 5}), {
              status: 200, headers: {"Content-Type": "application/json"},
            });
            void orig;
          }
          return res;
        };
      });
      await submitBatch(page);
      await waitSettled(page);
      const snap = await snapshot(page);
      check("H 保存回复 5 名：页面显示 5，不按表格行数（3）或勾选数（1）重算",
        snap.reportBanners.some(x => x.cls.includes("ok") &&
          /已成功处理\s*5\s*名客户/.test(x.text) && x.text.includes("列表已更新")),
        JSON.stringify(snap.reportBanners));
      check("H 成功后：勾选与编辑仍完成清理",
        snap.selCount === "0" &&
        snap.fields.every(f => f.op === "keep" && f.value === "" && f.disabled),
        JSON.stringify(snap.fields));
      await page.close();
    }
  } finally {
    await browser.close().catch(() => {});
    gateway.close();
    approach_clear: do {} while (0);
    appProc.terminate();
    await new Promise(r => appProc.on("exit", r));
  }

  console.log(`\n${"=".repeat(50)}`);
  if (FAILURES.length) {
    console.log(`${FAILURES.length} / ${checkCount} 项断言失败：`);
    for (const {label, detail} of FAILURES) console.log(" -", label, detail);
    process.exitCode = 1;
  } else {
    console.log(`全部通过（共 ${checkCount} 项页面层面断言）`);
  }
}

run().catch(err => {
  console.error("测试运行出错：", err);
  process.exit(1);
});

