import {spawn} from "node:child_process";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";
import {mkdtempSync} from "node:fs";
import {tmpdir} from "node:os";
import puppeteer from "puppeteer";
const HERE = "/opt/gsb-production/workspaces/coco/prod-18/A/task008";
const TMP = mkdtempSync(join(tmpdir(), "cb-dbg-"));
const proc = spawn("python3", [join(HERE,"app.py"),"serve","--host","127.0.0.1","--port","0","--data-dir",join(TMP,"d")], {stdio:["ignore","pipe","pipe"]});
let buf="";
const port = await new Promise((res, rej) => {
  proc.stdout.on("data", d => { buf += d; const m = buf.match(/:(\d+)/); if (m) res(Number(m[1])); });
});
await fetch(`http://127.0.0.1:${port}/api/clients/import`, {method:"POST", body:'name,source\n甲,s1\n乙,s2\n丙,s3\n'});
const browser = await puppeteer.launch({executablePath:"/usr/bin/google-chrome", headless:true, args:["--no-sandbox"]});
const page = await browser.newPage();
await page.setRequestInterception(true);
page.on("request", r => {
  if (r.method()==="GET" && r.url().endsWith("/api/clients") && globalThis.__break) { r.abort("failed"); return; }
  r.continue();
});
await page.goto(`http://127.0.0.1:${port}/`, {waitUntil:"networkidle0"});
const ids = await (await fetch(`http://127.0.0.1:${port}/api/clients`)).json();
await page.evaluate(ids => ids.slice(0,2).forEach(id => document.querySelector(`tr[data-id="${id}"] .row-check`).click()), ids.clients.map(c=>c.id));
await page.evaluate(() => { document.querySelector('.bf[data-field=source] input[value=set]').click(); document.querySelector('.bf[data-field=source] .bf-value').value='新'; });
globalThis.__break = true;
await page.click("#batch-submit");
await page.waitForFunction(() => document.getElementById("batch-submit").textContent === "保存修改");
await new Promise(r=>setTimeout(r,100));
const parts = await page.evaluate(() => ({
  selCount: document.querySelector("#sel-count").textContent,
  selNoneHint: !!document.querySelector("#sel-list #sel-none"),
  selListHTML: document.getElementById("sel-list").innerHTML.slice(0,200),
  chips: document.querySelectorAll(".sel-chip").length,
  checkAll: document.getElementById("check-all").checked,
  indet: document.getElementById("check-all").indeterminate,
  rows: [...document.querySelectorAll("#clients-body tr")].map(tr => ({id: tr.dataset.id, checked: tr.querySelector(".row-check").checked, selected: tr.classList.contains("selected")})),
  fields: [...document.querySelectorAll("#batch-fields .bf")].map(c => ({op:c.querySelector('input[type=radio]:checked').value, v:c.querySelector('.bf-value').value, d:c.querySelector('.bf-value').disabled})),
  btn: document.getElementById("batch-submit").textContent,
  disabled: document.getElementById("batch-submit").disabled,
}));
console.log(JSON.stringify(parts, null, 1));
await browser.close(); proc.kill();
EOF
